INSERT INTO public.meetings (title, group_name, category, tagline, description, starts_at, venue, address, city, state, zip_code, latitude, longitude, host_name, attendee_count, is_virtual, cost_description, status, source, source_url, last_verified_at) VALUES ('CA Landlord Laws - What Investors Need to Know w/ Rachid Abadli', 'West Sacramento Real Estate Investor Meetup', 'Real Estate', 'Join us this month for a discussion about how California''s landlord-tenant laws have changed dramatically — and most rental investors don''t', 'Join us this month for a discussion about how California''s landlord-tenant laws have changed dramatically — and most rental investors don''t realize how exposed they are. This practical, no-fluff session covers the rules that actually trip landlords up and cost them money: AB 1482 rent caps, just-cause eviction requirements, new security deposit limits, and disclosure obligations that apply whether you own 1 unit or 100. Rachid will walk through real scenarios, common mistakes, and simple steps More info: https://www.meetup.com/west-sacramento-real-estate-investor-meetup/events/316911457/', '2026-10-27T18:00:00-07:00', 'Burgers and Brew', '317 3rd St', 'West Sacramento', 'CA', '', 38.59, -121.54, 'West Sacramento Real Estate Investor Meetup', 4, false, 'Free', 'live', 'meetup', 'https://www.meetup.com/west-sacramento-real-estate-investor-meetup/events/316911457/', now()) ON CONFLICT (source_url) WHERE source_url IS NOT NULL DO UPDATE SET attendee_count=EXCLUDED.attendee_count, starts_at=EXCLUDED.starts_at, status='live', last_verified_at=now();
